'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = x => x ? new Date(x).toLocaleString('fr-FR', {day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '—';
const paths = {grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v15',lab:'M9 3h6 M10 3v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3 M8 15h8',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',arrow:'M4 12h16 M14 6l6 6-6 6',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',plus:'M12 5v14 M5 12h14',close:'M6 6l12 12 M6 18L18 6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',external:'M14 3h7v7 M21 3L10 14 M10 3H3v18h18v-7',check:'M5 12l4 4L20 5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',spark:'M12 3l2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z',folder:'M3 6V4h6l3 3h9v13H3z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',activity:'M2 12h5l3-8 4 16 3-8h5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',edit:'M4 16L16 4l4 4L8 20H4z M14 6l4 4',copy:'M8 8h13v13H8z M16 8V3H3v13h5',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.spark}"/></svg>`;
const badge = (text, cls='') => `<span class="badge ${cls}">${esc(text)}</span>`;
const button = (text, action, ico, cls='', attrs='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ico ? icon(ico) : ''}${esc(text)}</button>`;
const SAMPLE = 'En charge rapide, nos cellules dépassent 45 °C et vieillissent deux fois plus vite. On cherche à limiter l’échauffement sans alourdir le pack.';
const roleNames = {lecteur:'Lecteur',opportunite:'Opportunité',rapprochement:'Rapprochement',incorporation:'Incorporation',research_task:'Travaux de recherche'};
const statusNames = {queued:'En attente',running:'En cours',succeeded:'Terminée',failed:'Échec',interrupted:'Interrompue',pending:'À décider',accepted:'Acceptée',rejected:'Refusée',invalidated:'Contrat modifié',sending:'Envoi en cours',delivery_unknown:'Livraison à vérifier'};
const S = {view:'overview',role:'lab',mode:'live',data:null,problem:localStorage.getItem('passage-problem') || '',search:null,filter:'',status:'all',detail:null,tab:'lecture',job:null,connections:null};
let toastTimer, modalReturn;
async function api(path, options={}) {
  const response = await fetch('/api' + path, {...options, headers:{'Content-Type':'application/json','X-Passage-Role':S.role,'X-Passage-CSRF':S.csrf||'',...options.headers}});
  if (!response.ok) {
    let body; try {body = await response.json();} catch {body = {detail:'Le serveur n’a pas répondu correctement.'};}
    throw new Error(typeof body.detail === 'string' ? body.detail : JSON.stringify(body.detail));
  }
  return response.json();
}
const post = (path, data={}) => api(path, {method:'POST',body:JSON.stringify(data)});
function toast(message, error=false) {clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',error?9000:4500);}
function errorBox(message){return `<div class="notice error" role="alert">${esc(message)}</div>`;}
async function refresh(){S.data=await api('/state');}
function findThesis(id){return S.data.theses.find(t=>t.id===id);}
function author(t){return t.authors.map(a=>a.name).join(', ') || 'Auteur non renseigné';}
function thesisStatus(t){return badge(t.status==='enCours'?'En cours':t.status==='soutenue'?'Soutenue':t.status,t.status==='enCours'?'amber':'gray');}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
function empty(message,ico='book'){return `<div class="empty">${icon(ico)}${esc(message)}</div>`;}
function nav(view,label,ico,count=''){return `<button data-action="nav" data-view="${view}" class="${S.view===view?'active':''}">${icon(ico)}${label}${count!==''?`<span class="count">${count}</span>`:''}</button>`;}
function shell(){
  const titles={teams:'Mes équipes',chat:'Projets & dialogue',work:'Travaux de recherche',overview:'Vue d’ensemble',lab:'Le laboratoire',library:'Bibliothèque',researcher:'Mes recherches',programmes:'Programmes R&D',agents:'Atelier des agents',activity:'Exécutions',connections:'Connexions'};
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark"></span>Passage<span class="tiny muted">↗</span></div><p class="tagline">De la recherche à l’usage.</p><div class="navlabel">Espace de travail</div><nav class="nav" aria-label="Navigation principale">${nav('chat','Projets & dialogue','spark')}${nav('work','Travaux de recherche','folder')}${nav('teams','Mes équipes','user')}${nav('overview','Vue d’ensemble','grid')}${nav('lab','Le laboratoire','lab',S.data.stats.lab)}${nav('library','Bibliothèque','book')}${nav('researcher','Mes recherches','user')}${nav('programmes','Programmes R&D','folder')}</nav><div class="navlabel">Orchestration</div><nav class="nav" aria-label="Administration">${S.user?.role==='admin'?nav('agents','Atelier des agents','spark',S.data.agents.length):''}${nav('activity','Exécutions','activity')}${nav('connections','Connexions','link')}${S.user?.role==='admin'?'<button data-action="accounts">Comptes & rôles</button>':''}</nav><div class="side-bottom"><div class="workspace"><span class="avatar">${esc((S.user?.name||'P').slice(0,2).toUpperCase())}</span><div><p>${esc(S.user?.name||'Mon espace')}</p><small>${esc(({lab:'Laboratoire',researcher:'Doctorant / chercheur',company:'Entreprise',admin:'Administration'})[S.user?.account_type||S.user?.role]||'Espace personnel')}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Espace de travail <span>/</span> <strong>${titles[S.view]}</strong></div><div class="top-actions"><span class="top-mode"><i class="mode-dot"></i>Hackathon X-IA</span><span class="top-mode">Agents réels</span><select id="role-select" aria-label="Rôle de travail" ${S.user?.role!=='admin'?'disabled':''}>${[['lab','Laboratoire · directeur'],['researcher','Doctorant'],['company','Entreprise · R&D'],['admin','Administrateur']].map(([id,n])=>`<option value="${id}" ${S.role===id?'selected':''}>${n}</option>`).join('')}</select>${button('Déconnexion','logout',null,'ghost small')}</div></header><div class="content" id="content" tabindex="-1"></div></main></div>`;
  renderView();
}
function renderView(){
  const views={teams:teamsPage,chat:chatPage,work:workPage,overview:overview,lab:lab,library:library,researcher:researcher,programmes:programmes,agents:agentPage,activity:activity,connections:connectionsPage};
  $('#content').innerHTML=views[S.view]()+`<div id="job-inline">${jobHtml()}</div><div class="footer-note"><span>Passage · prototype du hackathon X-IA · nom provisoire</span><span>Les agents proposent. Vous décidez.</span></div>`;
  if(S.view==='chat'&&typeof syncVoiceControls==='function')syncVoiceControls();
  if(S.view==='chat')requestAnimationFrame(()=>{const el=$('#messages');if(el)el.scrollTop=el.scrollHeight;});
  if(S.view==='activity') loadRuns();
  if(S.view==='teams')loadTeams();
  if(S.view==='connections'){loadConnections();loadPartners();loadBrainAccounts();loadVoiceAccount();loadJinkoAccount();}
}
function overview(){const d=S.data;return heading('Recherche & entrepreneuriat','Faire circuler les idées.','Vos travaux, leurs usages possibles et les échanges qui se construisent.',button('Explorer la bibliothèque','nav','arrow','secondary','data-view="library"'))+
 `<section class="hero"><div><div class="eyebrow">Du laboratoire au terrain</div><h2>Une recherche peut ouvrir<br>une nouvelle voie.</h2><p>Partez d’un besoin concret, trouvez les travaux pertinents et construisez un premier chemin vers leur utilisation.</p><div class="actions">${button('Essayer le besoin des batteries','sample-search','search','lime')}${button('Voir le laboratoire','nav',null,'ghost','data-view="lab"')}</div></div><div class="journey-art" aria-hidden="true"><div class="orbit">${icon('lab')}</div><span class="connector-line"></span><div class="orbit central">${icon('spark')}</div><span class="connector-line"></span><div class="orbit">${icon('folder')}</div></div></section>
 <div class="stats">${[[d.stats.lab,'Thèses du laboratoire','Notices réelles · theses.fr','lab'],[d.stats.visible,'Fiches dans la bibliothèque','Visibilité contrôlée par le laboratoire','book'],[d.stats.visits,'Signaux d’intérêt','Entreprises distinctes par thèse','eye'],[d.stats.reports,'Dossiers préparés','Lectures, opportunités et incorporation','folder']].map(([n,title,sub,ico])=>`<div class="stat"><div class="top">${title}${icon(ico)}</div><strong>${n}</strong><small>${sub}</small></div>`).join('')}</div>
 <div class="grid two"><section><div class="sectionhead"><h2>Au fil de la recherche</h2>${button('Toutes les thèses','nav','arrow','ghost small','data-view="lab"')}</div><div class="card flush">${thesisTable(d.theses.filter(t=>t.is_lab).slice(0,4),true)}</div><div class="notice info">Le corpus comprend des notices publiques réelles. Les publications et l’entreprise du scénario sont simulées ; elles n’engagent pas les laboratoires.</div></section><section><div class="sectionhead"><h2>Derniers mouvements</h2>${icon('activity')}</div><div class="card"><div class="timeline">${d.events.length?d.events.slice(0,5).map(e=>`<div class="event"><span class="event-dot"></span><div><p>${esc(e.action)}</p><small>${esc(e.detail || e.subject)}<br>${fmt(e.at)}</small></div></div>`).join(''):empty('Les premières actions apparaîtront ici.','activity')}</div></div></section></div>`;}
function thesisTable(rows,compact=false){if(!rows.length)return empty('Aucune thèse ne correspond à ces filtres.');return `<div class="table-wrap"><table><thead><tr><th>Thèse & auteur</th>${compact?'':'<th>Laboratoire</th>'}<th>État</th><th>${compact?'':'Visibilité'}</th></tr></thead><tbody>${rows.map(t=>`<tr><td><button class="title-button" data-action="thesis" data-id="${esc(t.id)}">${esc(t.title)}</button><span class="subline">${esc(author(t))} · ${esc(t.date || t.start_date || 'Date inconnue')}</span></td>${compact?'':`<td><span class="tiny">${esc(t.is_lab?S.data.settings.lab_short:t.institution)}</span>${t.has_reading?'<span class="subline">Fiche de lecture prête</span>':''}</td>`}<td>${thesisStatus(t)}</td><td>${compact?button('Ouvrir','thesis','arrow','ghost small',`data-id="${esc(t.id)}"`):badge(t.visible?'Visible':'Privée',t.visible?'dark':'gray')}</td></tr>`).join('')}</tbody></table></div>`;}
function filters(){return `<form id="filter-form" class="toolbar"><input name="query" value="${esc(S.filter)}" placeholder="Rechercher un titre, un auteur, un sujet…" aria-label="Filtrer les thèses"><select name="status" aria-label="État de la thèse"><option value="all">Tous les états</option><option value="enCours" ${S.status==='enCours'?'selected':''}>En cours</option><option value="soutenue" ${S.status==='soutenue'?'selected':''}>Soutenues</option></select><button class="btn secondary" type="submit">${icon('search')}Filtrer</button></form>`;}
function filtered(rows){const q=S.filter.toLocaleLowerCase();return rows.filter(t=>(!q || (t.title+' '+author(t)+' '+t.keywords.join(' ')).toLocaleLowerCase().includes(q))&&(S.status==='all'||t.status===S.status));}
function lab(){const rows=filtered(S.data.theses.filter(t=>t.is_lab));return heading('Espace laboratoire',S.data.settings.lab_short+' · '+S.data.settings.city,'Donnez de la visibilité aux travaux de votre équipe, à votre rythme.',button('Importer depuis theses.fr','import','download'))+
 `<div class="grid equal" style="margin-bottom:24px"><div class="card"><div class="sectionhead"><h3 style="margin:0">${esc(S.data.settings.lab_name)}</h3>${button('Modifier','edit-lab','edit','ghost small')}</div><p class="muted tiny">${S.data.stats.lab} notices · ${S.data.theses.filter(t=>t.is_lab&&t.visible).length} visibles · ${S.data.theses.filter(t=>t.is_lab&&t.has_reading).length} lues</p><div class="actions">${button('Lire les fiches non traitées','batch','spark','secondary small')}${button('Exporter les indicateurs','export-lab','download','ghost small')}</div></div><div class="card"><h3>Vous gardez la main sur la publication.</h3><p class="muted" style="font-size:12px;margin-bottom:0">Les nouvelles notices sont privées. Ouvrez une fiche pour lire l’analyse, la corriger et décider de sa visibilité. Une thèse peut être retirée à tout moment.</p></div></div>${filters()}<div class="card flush"><div class="card-caption"><span>${rows.length} travaux dans votre périmètre</span><span class="muted tiny">Statuts fournis par theses.fr</span></div>${thesisTable(rows)}</div>`;}
function researcher(){return heading('Espace doctorant','Mes recherches','Consultez votre fiche, apportez vos corrections et suivez les marques d’intérêt.')+`<div class="notice info">Le profil doctorant est joué pour la démonstration. Choisissez une thèse ; votre compte détermine vos droits sur cette installation.</div>${filters()}<div class="card flush">${thesisTable(filtered(S.data.theses))}</div>`;}
function library(){const rows=filtered(S.data.theses.filter(t=>t.visible));return heading('Bibliothèque ouverte','Quel problème cherchez-vous à résoudre ?','Décrivez votre besoin avec vos mots. Les agents rapprochent les recherches et expliquent leurs limites.')+
 `<form id="search-form" class="search-panel"><label for="problem">Votre besoin industriel</label><textarea id="problem" name="problem" required minlength="10" placeholder="Par exemple : limiter l’échauffement de nos batteries pendant la charge rapide…">${esc(S.problem)}</textarea><div class="search-footer"><button type="button" class="sample" data-action="sample">Utiliser le cas des vélos électriques</button><div class="actions">${button('Dicter','dictate','mic','secondary')}<button type="submit" class="btn">${icon('spark')}Trouver des travaux utiles</button></div></div><div class="hint">${S.mode==='demo'?'Simulation : classement illustratif sans appel à un modèle.':'Appel réel de l’agent Rapprochement ; jusqu’à 25 fiches publiques présélectionnées.'}</div></form>`+
 (S.search?renderMatches(S.search):`<div class="sectionhead"><h2>La recherche à portée de main</h2>${badge(rows.length+' fiches visibles','gray')}</div>${filters()}<div class="card flush">${thesisTable(rows)}</div>`);}
function renderMatches(report){return `<div class="sectionhead"><div><h2>${report.content.matches.length} travaux examinés</h2><p class="tiny muted" style="margin:6px 0">${esc(report.agent_name)} · révision ${report.revision} · ${esc(report.model)} · ${fmt(report.created_at)}</p></div>${button('Revenir au catalogue','clear-search',null,'ghost small')}</div>${report.mode==='demo'?'<div class="notice">Classement simulé à partir des termes des notices. Ce résultat ne remplace pas une évaluation par le modèle.</div>':''}${report.content.matches.map((m,i)=>{const t=findThesis(m.thesis_id);if(!t||!t.visible)return '';return `<article class="result-card"><span class="rank">${String(i+1).padStart(2,'0')}</span><div class="result-main"><div class="pills">${badge(m.score>=50?'Piste à examiner':m.score>10?'Lien indirect':'Peu pertinent',m.score>=50?'dark':m.score>10?'amber':'gray')}${thesisStatus(t)}</div><h3><button class="title-button" data-action="thesis" data-id="${esc(t.id)}">${esc(t.title)}</button></h3><span class="subline">${esc(author(t))} · ${esc(t.institution)}</span><p class="reason">${esc(m.reason)}</p><small class="muted">Confiance : ${esc(m.confidence)} · ${esc(m.checks[0]||'Vérifications à préciser')}</small></div><div class="result-side"><div class="score">${m.score}<small> / 100<br>pertinence estimée</small></div>${button('Étudier la piste','thesis','arrow','secondary small',`data-id="${esc(t.id)}" data-tab="incorporation"`)}</div></article>`;}).join('')}`;}
function programmes(){const mode=S.data.oscar_mode;const ps=S.data.programmes.filter(p=>mode==='mcp'?p.source==='mcp':p.source==='demo');return heading('Entreprise · recherche & développement','Des pistes pour vos programmes.','Chaque proposition attend une décision. Une acceptation dépose une note dans le programme.',button(mode==='mcp'?'Rafraîchir depuis Oscar':'Nouveau programme',mode==='mcp'?'sync-oscar':'new-programme',mode==='mcp'?'link':'plus'))+
 `<div class="notice info">${mode==='mcp'?'Oscar connecté par configuration — les appels seront vérifiés à l’exécution.':'Mode démonstration — Oscar non connecté. Les programmes de Vélia Mobilité sont fictifs.'}</div><div class="grid equal">${ps.length?ps.map(p=>`<section class="card"><div class="programme-header"><h3>${esc(p.name)}</h3>${badge(p.source==='demo'?'Démo':'Oscar','gray')}</div><p class="programme-description textwrap">${esc(p.description)}</p>${button('Chercher des thèses pour ce programme','programme-search','search','secondary small',`data-id="${esc(p.id)}"`)}<div style="margin-top:24px"><div class="panel-subtitle">Propositions</div>${S.data.proposals.filter(x=>x.programme_id===p.id).map(x=>`<div class="proposal"><div class="pills">${badge(statusNames[x.status]||x.status,x.status==='accepted'?'dark':x.status==='pending'?'amber':'gray')}</div><h3 style="margin-top:10px">${esc(x.thesis_title)}</h3><p class="tiny muted">${fmt(x.created_at)}</p><div class="actions">${button('Consulter','thesis',null,'ghost small',`data-id="${esc(x.thesis_id)}"`)}${x.status==='pending'?button('Accepter','decide','check','small',`data-id="${x.id}" data-decision="accepted"`)+button('Refuser','decide',null,'secondary small',`data-id="${x.id}" data-decision="rejected"`):''}${x.status==='accepted'?button('Voir la note','show-note','book','secondary small',`data-id="${x.id}"`):''}</div>${x.status==='accepted'?`<p class="hint" style="margin-top:15px">Préparer une rencontre · ${esc(x.city)}. Réservation de voyage non connectée.</p>`:''}</div>`).join('')||'<p class="tiny muted">Aucune proposition pour le moment.</p>'}</div></section>`).join(''):empty('Rafraîchissez les programmes depuis Oscar.','folder')}</div>`;}
function agentPage(){return heading('Cerveau + harnais','L’atelier des agents.','Définissez leur mission, leurs connaissances et leurs outils. Gardez une version de chaque évolution.',button('Créer un agent','new-agent','plus'))+
 `<div class="notice info">Votre éditeur est la source de vérité. Dust exécute les agents publiés ; Pipelex porte leurs méthodes. Les définitions restent ici.</div><div class="grid equal">${S.data.agents.filter(a=>a.active||!(a.id in roleNames && a.revision<=2)).map(a=>`<article class="card agent-card"><div class="agent-top"><span class="agent-icon">${icon(a.role==='lecteur'?'book':a.role==='opportunite'?'spark':a.role==='rapprochement'?'link':'folder')}</span><div class="pills">${badge(a.active?'Actif pour ce rôle':'Brouillon',a.active?'dark':'gray')}${badge('v'+a.revision,'gray')}</div></div><h3>${esc(a.name)}</h3><p>${esc(a.mandate)}</p><div class="meta"><span>${esc(a.engine)}</span><span>·</span><span>${esc(a.model)}</span><span>·</span><span>${a.tools.length+a.connector_ids.length} capacités</span></div><div class="actions">${button('Ouvrir le harnais','edit-agent','edit','secondary small',`data-id="${a.id}"`)}${button('Tester','test-agent','spark','ghost small',`data-id="${a.id}"`)}</div>${a.live_control.length?`<p class="hint" style="margin:12px 0 0">${esc(a.live_control[0])}</p>`:''}</article>`).join('')}</div>`;}
function activity(){return heading('Traçabilité','Ce qui a été exécuté.','Retrouvez les sources, la version du harnais et le résultat de chaque tâche.',button('Rafraîchir','refresh','activity','secondary'))+`<div class="card flush" id="runs-list">${empty('Chargement des exécutions…','clock')}</div>`;}
async function loadRuns(){try{const rows=await api('/runs');if(!$('#runs-list'))return;$('#runs-list').innerHTML=rows.length?rows.map(r=>`<div class="runrow"><span class="agent-icon">${icon(r.kind==='agent'?'spark':'activity')}</span><div class="grow"><p>${esc(r.label)}</p><small>${fmt(r.created_at)} · ${esc(r.model||r.kind)} ${r.duration?'· '+r.duration+' s':''}</small>${r.error?`<p class="ui-error">${esc(r.error)}</p>`:''}</div>${badge(statusNames[r.status]||r.status,r.status==='succeeded'?'dark':r.status==='failed'?'red':'amber')}${button('Détails','run-detail','arrow','ghost small',`data-id="${r.id}"`)}</div>`).join(''):empty('Aucune exécution. Lancez une lecture ou une recherche.','activity');}catch(e){toast(e.message,true);}}
function connectionsPage(){return heading('Outils & moteurs','Les connexions du harnais.','Chaque personne connecte ses comptes ChatGPT, Dust et Pipelex ci-dessous. Les clés API de l’installation sont des accès distincts, réservés à l’administrateur.')+`<div class="card connection-card"><h3>Connexion à Passage avec Google</h3><p>${S.user.google_linked?'Compte Google associé à votre compte Passage.':'Votre compte Passage peut être associé à Google sans donner accès à Gmail ni à Drive.'}</p>${S.googleEnabled&&!S.user.google_linked?button('Associer mon compte Google','google-link','link','secondary small'):S.googleEnabled?badge('Associé','dark'):'<p class="hint">Configuration OAuth Google requise sur cette installation.</p>'}</div><div id="voice-account"></div><div id="jinko-account"></div><div id="brain-accounts"></div><div id="partners-content"></div><div class="notice info"><strong>Clés API de l’installation</strong><p>Les réglages Dust et Pipelex ci-dessous concernent les moteurs API des agents publiés. Leur mention « À configurer » ne remet pas en cause la connexion personnelle MCP affichée au-dessus.</p></div><div id="connections-content">${empty('Chargement des connexions…','link')}</div>`;}
async function loadConnections(){if(S.user?.role!=='admin'){if($('#connections-content'))$('#connections-content').innerHTML='<p class="muted">Les clés API de cette installation sont gérées par son administrateur. Vos connexions MCP sont personnelles.</p>';return;}try{S.connections=await api('/connections');if(!$('#connections-content'))return;const c=S.connections;$('#connections-content').innerHTML=`<div class="notice info">« Configuré » indique la présence de paramètres. Une exécution réussie est nécessaire pour vérifier l’accès au service. Cochez « Conserver sur cette installation » pour retrouver ces réglages après redémarrage.</div><form id="connections-form"><div class="grid equal">${connectionCard('Gradium','Transcription et lecture des réponses du dialogue.',c.secrets.GRADIUM_API_KEY,secretField('GRADIUM_API_KEY','Clé API Gradium',c)+textField('GRADIUM_VOICE_ID','Identifiant de voix Gradium',c.values.GRADIUM_VOICE_ID))}${connectionCard('OpenAI','Clé API facultative pour les agents qui choisissent explicitement OpenAI API.',c.openai,secretField('OPENAI_API_KEY','Clé API OpenAI',c))}${connectionCard('Dust','Publiez la définition depuis l’atelier avant son exécution.',c.dust,secretField('DUST_API_KEY','Clé API Dust',c)+textField('DUST_WORKSPACE_ID','Identifiant du workspace',c.values.DUST_WORKSPACE_ID)+textField('DUST_BASE_URL','Adresse Dust',c.values.DUST_BASE_URL||'https://dust.tt'))}${connectionCard('Pipelex','Exécute une méthode publiée. Exportez le .mthds depuis l’agent ; indiquez sa référence et sa version.',c.pipelex,secretField('PIPELEX_API_KEY','Clé API Pipelex',c)+textField('PIPELEX_METHOD_REF','Référence de méthode par défaut',c.values.PIPELEX_METHOD_REF))}${connectionCard('Modèle local / API compatible','Endpoint Chat Completions, modèle configuré dans le harnais.',c.compatible,textField('COMPATIBLE_BASE_URL','URL du serveur',c.values.COMPATIBLE_BASE_URL||'http://localhost:11434/v1')+secretField('COMPATIBLE_API_KEY','Clé éventuelle',c))}<details class="card"><summary>Ajouter un modèle local</summary>${connectionCard('Ollama local','Appels réels sur les modèles déjà présents. Choisir Ollama et le nom du modèle dans le harnais.',false,textField('OLLAMA_BASE_URL','Adresse Ollama',c.values.OLLAMA_BASE_URL||'http://127.0.0.1:11434')+button('Lister les modèles locaux','local-models','search','secondary small'))}</details>${connectionCard('Latitude · auto-hébergé','Traces des exécutions sans contenu des requêtes ni réponses. Nécessite votre instance Latitude, un projet et une clé ingest.',c.latitude,`<div class="field"><label for="LATITUDE_ENABLED">Export des traces</label><select id="LATITUDE_ENABLED" name="LATITUDE_ENABLED"><option value="off" ${c.values.LATITUDE_ENABLED==='on'?'':'selected'}>Désactivé</option><option value="on" ${c.values.LATITUDE_ENABLED==='on'?'selected':''}>Activé</option></select></div>`+textField('LATITUDE_INGEST_URL','URL ingest auto-hébergée',c.values.LATITUDE_INGEST_URL||'http://127.0.0.1:3002')+textField('LATITUDE_PROJECT_SLUG','Slug du projet Latitude',c.values.LATITUDE_PROJECT_SLUG)+secretField('LATITUDE_API_KEY','Clé API Latitude',c))}<div class="card connection-card span2"><div class="status-row"><h3>Oscar-AI · programmes de R&D</h3>${badge(c.oscar==='mcp'?'MCP configuré':'Mode démonstration','gray')}</div><p>Trois outils : lire les projets, lire leur contexte et déposer une note après acceptation.</p><div class="form-grid"><div class="field"><label for="PASSAGE_OSCAR">Mode Oscar</label><select id="PASSAGE_OSCAR" name="PASSAGE_OSCAR"><option value="demo" ${c.oscar==='demo'?'selected':''}>Démonstration locale</option><option value="mcp" ${c.oscar==='mcp'?'selected':''}>Connexion MCP</option></select></div>${textField('OSCAR_URL','Adresse Oscar',c.values.OSCAR_URL||'http://127.0.0.1:8000')}${textField('OSCAR_MCP_SCRIPT','Chemin du serveur oscar_mcp.py',c.values.OSCAR_MCP_SCRIPT)}${textField('OSCAR_COMPANY','Identifiant entreprise',c.values.OSCAR_COMPANY||'1')}${secretField('OSCAR_TOKEN','Jeton d’agent Oscar',c)}</div></div></div><div class="actions" style="margin:20px 0 35px"><label class="check"><input type="checkbox" name="persist_settings">Conserver sur cette installation (chiffré)</label><button class="btn" type="submit">${icon('check')}Appliquer les réglages</button></div></form><div class="sectionhead"><h2>Boîte à outils MCP</h2>${button('Ajouter un connecteur','new-connector','plus','secondary')}</div><div class="grid equal">${c.connectors.map(x=>`<div class="card"><div class="status-row"><h3>${esc(x.name)}</h3>${badge(x.enabled?'Activé':'Désactivé',x.enabled?'dark':'gray')}</div><p class="tiny muted textwrap">${esc(x.url)}</p><p class="tiny">${x.allowed_tools.length} outils autorisés</p><div class="actions">${button('Configurer','edit-connector','settings','secondary small',`data-id="${x.id}"`)}${button('Tester la connexion','test-connector','link','ghost small',`data-id="${x.id}"`)}</div></div>`).join('')||'<div class="card"><p class="muted">Ajoutez un serveur MCP, testez sa liste d’outils puis autorisez ceux qui seront utilisables par un agent.</p></div>'}</div><div class="notice info">Voix : Gradium transcrit vos commandes et lit les réponses dans le dialogue. Configurez une clé API et un identifiant de voix ; les appels réels dépendent de ces accès.</div>`;}catch(e){if($('#connections-content'))$('#connections-content').innerHTML=errorBox(e.message);}}
function connectionCard(name,description,configured,fields){if(name==='Ollama local'&&!S.data?.agents?.some(a=>a.provider==='ollama'))return '';return `<div class="card connection-card"><div class="status-row"><h3>${name}</h3>${badge(configured?'Configuré':'À configurer',configured?'dark':'gray')}</div><p>${description}</p>${fields}</div>`;}
function textField(name,label,value='',type='text',required=false){return `<div class="field"><label for="${name}">${esc(label)}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`;}
function textArea(name,label,value='',rows=4){return `<div class="field"><label for="${name}">${esc(label)}</label><textarea id="${name}" name="${name}" rows="${rows}">${esc(value)}</textarea></div>`;}
function secretField(name,label,c){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="password" autocomplete="new-password" placeholder="${c.secrets[name]?'Déjà configurée — laisser vide pour conserver':'Non configurée'}"><div class="hint">La valeur n’est jamais renvoyée par le serveur.</div></div>`;}
function modal(title,html,footer='',cls=''){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="dialog-backdrop"><section class="dialog ${cls}" role="dialog" aria-modal="true" aria-labelledby="dialog-label"><header class="dialog-head"><h2 id="dialog-label">${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="Fermer">${icon('close')}</button></header><div class="dialog-body">${html}<div id="modal-error"></div></div>${footer?`<footer class="sticky-actions">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';$('.dialog .close').focus();}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';if(modalReturn&&document.contains(modalReturn))modalReturn.focus();}
async function openThesis(id,tab='lecture'){if(S.role==='company')await post('/theses/'+encodeURIComponent(id)+'/visit');S.detail=await api('/theses/'+encodeURIComponent(id));S.tab=tab;renderThesis();}
function currentReport(role){return S.detail.reports.find(r=>r.role===role&&r.mode===S.mode)||S.detail.reports.find(r=>r.role===role);}
function renderThesis(){const {thesis:t,visits,proposals}=S.detail;const canEdit=['lab','researcher'].includes(S.role);let body=`<div class="pills">${thesisStatus(t)}${badge(t.visible?'Visible dans la bibliothèque':'Fiche privée',t.visible?'dark':'gray')}${badge(t.id,'gray')}</div><h1 class="dialog-title">${esc(t.title)}</h1><div class="detail-meta"><span>${icon('user')} ${esc(author(t))}</span><span>${esc(t.institution)}</span><span>${esc(t.date||t.start_date)}</span></div><p class="tiny muted">${esc(t.labs.join(' · '))}</p><div class="actions"><a href="${esc(t.source_url)}" class="source-link" target="_blank" rel="noopener noreferrer">Notice theses.fr ${icon('external')}</a>${S.role==='lab'?button(t.visible?'Retirer de la bibliothèque':'Rendre visible','visibility','eye','secondary small',`data-id="${t.id}" data-visible="${!t.visible}"`):''}${badge(visits+' entreprise'+(visits>1?'s':''),'blue')}</div><div class="tabs" role="tablist">${[['lecture','La fiche'],['opportunite','Opportunité'],['incorporation','Incorporation'],['activity','Activité']].map(([k,n])=>`<button role="tab" aria-selected="${S.tab===k}" data-action="detail-tab" data-tab="${k}" class="${S.tab===k?'active':''}">${n}</button>`).join('')}</div>`;
 if(S.tab==='lecture'){const r=currentReport('lecteur');body+=t.correction?`<div class="card" style="margin-bottom:20px"><div class="sectionhead"><h3 style="margin:0">Résumé corrigé par l’équipe</h3>${badge('Correction humaine','dark')}</div><p class="report-summary textwrap">${esc(t.correction)}</p></div>`:'';body+=`<div class="actions" style="margin-bottom:20px">${S.role!=='company'?button(r?'Relancer la lecture':'Faire lire cette thèse','generate','spark','',`data-role="lecteur"`):''}${canEdit?button('Corriger le résumé','correct','edit','secondary'):''}</div>`+(r?renderReport(r):'<div class="notice info">Aucune fiche de lecture pour le moment. Le résumé source reste disponible ci-dessous.</div>')+`<details ${!r?'open':''}><summary>Résumé original et métadonnées</summary><p class="report-summary textwrap" style="margin-top:16px">${esc(t.abstract||'Aucun résumé disponible dans la notice.')}</p><div class="pills">${t.keywords.slice(0,15).map(k=>badge(k,'gray')).join('')}</div><p class="tiny muted" style="margin-top:15px">Direction : ${esc(t.directors.map(d=>d.name).join(', ')||'Non renseignée')}<br>Source collectée le ${fmt(t.collected_at)} · texte complet non analysé.</p></details>`;}
 else if(S.tab==='opportunite'){const r=currentReport('opportunite');body+=`<p class="muted">Cette recherche peut-elle ouvrir une piste entrepreneuriale ? L’analyse peut conclure qu’elle n’est pas suffisamment étayée.</p><div class="actions" style="margin-bottom:20px">${S.role!=='company'?button(r?'Actualiser le dossier':'Préparer le dossier','generate','spark','',`data-role="opportunite"`):''}</div>`+(r?renderReport(r):empty('Aucun dossier d’opportunité préparé.','spark'));}
 else if(S.tab==='incorporation'){const r=currentReport('incorporation');body+=`<form id="incorporation-form"><label for="inc-problem">Le besoin à rapprocher de cette thèse</label><textarea id="inc-problem" name="problem" required minlength="10">${esc(S.problem||r?.problem||'')}</textarea><div class="actions" style="margin:12px 0 22px"><button class="btn" type="submit">${icon('spark')}${r?'Actualiser le dossier':'Préparer l’incorporation'}</button>${button('Cas des batteries','sample-inc',null,'ghost small')}</div></form>`+(r?renderReport(r)+`<form id="followup-form" style="margin-top:24px"><label for="followup">Approfondir ce dossier</label><textarea id="followup" name="question" rows="2" required placeholder="Quelle première expérience permettrait de vérifier cette piste ?"></textarea><button class="btn secondary small" type="submit" style="margin-top:10px">${icon('arrow')}Poser la question</button></form>${S.role==='company'?`<div class="divider"></div><form id="proposal-form"><label for="programme-choice">Proposer cette piste à un programme</label><div class="toolbar"><select id="programme-choice" name="programme" required>${S.data.programmes.filter(p=>p.source===S.data.oscar_mode).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button class="btn" type="submit">Proposer ${icon('arrow')}</button></div><div class="hint">Le chef de programme devra accepter avant qu’une note soit déposée.</div></form>`:''}`:empty('Un dossier précis pour préparer les essais et la prise de contact.','folder'));}
 else{body+=`<div class="card"><h3>${visits} entreprise${visits>1?'s':''} distincte${visits>1?'s':''} a consulté cette fiche</h3><p class="tiny muted">Signal local du scénario. Le nom de l’auteur reste attaché à chaque dossier.</p></div><h3 style="margin-top:25px">Propositions aux programmes</h3>${proposals.map(p=>`<div class="list-line">${icon('folder')}<div><strong>${esc(p.programme_name)}</strong><br>${badge(statusNames[p.status]||p.status,'gray')}<span class="tiny muted"> · ${fmt(p.created_at)}</span></div></div>`).join('')||empty('Aucune proposition à ce jour.','folder')}<h3 style="margin-top:25px">Corrections humaines</h3>${S.detail.corrections.map(c=>`<details><summary>${fmt(c.at)} · ${esc(c.actor)}</summary><p class="textwrap">${esc(c.summary)}</p></details>`).join('')||'<p class="tiny muted">Aucune correction enregistrée.</p>'}`;}
 modal('Fiche de recherche',body,button('Fermer','close',null,'secondary')+`<span class="tiny muted">${t.publication_actor?esc(t.publication_actor):'La publication est une décision humaine.'}</span>`);}
function renderReport(r){const c=r.content;const block=(n,title,value)=>`<section class="report-block"><h3><span>${n}</span>${title}</h3>${Array.isArray(value)?`<ul>${value.map(v=>`<li>${esc(v)}</li>`).join('')||'<li>Aucun élément établi dans cette analyse.</li>'}</ul>`:`<p class="textwrap">${esc(value)}</p>`}</section>`;return `<article class="card"><div class="sectionhead"><div class="pills">${badge(r.mode==='demo'?'Simulation · sans LLM':'Appel réel',r.mode==='demo'?'amber':'dark')}${badge('Révision '+r.revision,'gray')}</div>${button('Exporter','export-report','download','ghost small',`data-id="${r.id}"`)}</div><p class="report-summary textwrap">${esc(c.summary)}</p>${c.verdict!=='sans objet'?`<p>${badge(c.verdict,c.verdict==='défavorable'?'red':'amber')}</p>`:''}${block('1','Pourquoi cette thèse',c.fit)}${block('2','Ce qui est documenté',c.demonstrated)}${block('3','Ce qui reste à vérifier',c.checks)}${block('4','Qui contacter',c.contacts)}${block('5','Confiance : '+esc(c.confidence),c.uncertainty)}<div class="divider"></div>${block('↗','Maturité',c.maturity.level+' — '+c.maturity.rationale+'\n'+c.maturity.uncertainty)}${block('§','Droits et accès',c.rights)}${c.application?block('→','Application envisagée',c.application):''}${c.steps.length?block('→','Prochaines étapes',c.steps):''}${r.role==='opportunite'?block('→','Marché et travaux proches',c.market+'\n'+c.competition):''}${r.role!=='lecteur'?block('≈','Ressources et délais',c.estimates):''}<details><summary>Preuves et provenance</summary>${c.evidence.map(e=>`<blockquote class="quote">${esc(e.quote)}<br><small>${esc(e.thesis_id)}</small></blockquote>`).join('')}<p class="tiny muted">${esc(r.agent_name)} · ${esc(r.engine)} · modèle déclaré : ${esc(r.model)}<br>${fmt(r.created_at)} · résumé et métadonnées uniquement</p>${r.sources.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.id)} ${icon('external')}</a>`).join(' · ')}</details></article>`;}
function jobHtml(){if(!S.job)return '';const j=S.job;return `<div class="job" role="status"><div class="head"><span>${['queued','running'].includes(j.status)?'<span class="spinner"></span>':''}${esc(j.label)}</span>${badge(statusNames[j.status]||j.status,j.status==='failed'?'red':'gray')}</div><p>${esc(j.error||j.trace?.at(-1)?.message||'Tâche enregistrée')}</p></div>`;}
async function watch(job,onDone){S.job=job;toast('Tâche lancée : '+job.label);if($('#job-inline'))$('#job-inline').innerHTML=jobHtml();let current=job;while(['queued','running'].includes(current.status)){await new Promise(r=>setTimeout(r,900));try{current=await api('/runs/'+job.id);}catch(e){toast('Suivi interrompu : '+e.message,true);return;}S.job=current;if($('#job-inline'))$('#job-inline').innerHTML=jobHtml();if($('#modal-job'))$('#modal-job').innerHTML=jobHtml();}await refresh();if(current.status==='succeeded'){toast('Traitement terminé.');await onDone?.(current.result);}else{toast(current.error||'Traitement interrompu',true);if($('#modal-error'))$('#modal-error').innerHTML=errorBox(current.error||'Traitement interrompu');}S.job=null;if($('#job-inline'))$('#job-inline').innerHTML='';if(!$('#modal-root').innerHTML)shell();}
async function generate(role,question=''){const t=S.detail.thesis;const req={role,thesis_id:t.id,problem:S.problem,mode:S.mode,question};const j=await post('/runs',req);if($('#modal-error'))$('#modal-error').innerHTML='<div id="modal-job">'+jobHtml()+'</div>';watch(j,async()=>{S.detail=await api('/theses/'+t.id);renderThesis();});}
async function download(path,name){const response=await fetch('/api'+path,{headers:{'X-Passage-Role':S.role}});if(!response.ok)throw new Error('Export impossible pour ce profil.');const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function changeView(view){closeModal();const previousRole=S.role;S.view=view;S.filter='';S.status='all';const roles={lab:'lab',researcher:'researcher',library:'company',programmes:'company',agents:'admin',connections:'admin'};if(roles[view]&&S.user?.role==='admin')S.role=roles[view];shell();window.scrollTo(0,0);if(S.role!==previousRole){await refresh();if(S.view===view)shell();}}
async function openAgent(id,duplicate=false){const d=await api('/agents/'+id);let a=d.agent;if(duplicate)a={...a,id:'',name:a.name+' — copie',active:false};if(a.role==='research_task')S.workCatalog=await api('/work/catalog');S.editAgent=a;const connectors=await api('/connections');modal(duplicate?'Dupliquer un agent':'Harnais · '+a.name,agentForm(a,d,connectors.connectors),`<div class="actions">${button('Fermer','close',null,'secondary')}${!duplicate?button('Dupliquer','duplicate-agent','copy','ghost',`data-id="${a.id}"`):''}</div><button class="btn" type="submit" form="agent-form">${icon('check')}Enregistrer une révision</button>`);}
function agentForm(a,d,connectors){return `<form id="agent-form"><div class="notice info">${a.id?'Révision '+a.revision+' · chaque exécution conserve sa définition.':'Nouvel agent · choisissez son mandat et son cerveau.'}</div><section class="card editor-section"><h3>01 · Identité & mandat</h3><div class="form-grid">${textField('name','Nom',a.name,'text',true)}<div class="field"><label for="agent-role">Rôle métier</label><select id="agent-role" name="role">${Object.entries(roleNames).map(([k,n])=>`<option value="${k}" ${a.role===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="span2">${textArea('mandate','Objectif et critères de réussite',a.mandate,2)}</div></div><label class="check"><input type="checkbox" name="active" ${a.active?'checked':''}>Utiliser cet agent pour son rôle métier</label><div class="hint">L’activation remplace l’agent actuellement actif de ce rôle.</div></section><section class="card editor-section"><h3>02 · Cerveau & exécution</h3><div class="form-grid"><div class="field"><label for="engine">Moteur</label><select id="engine" name="engine">${[['direct','Appel direct'],['dust','Dust'],['pipelex','Pipelex']].map(([k,n])=>`<option value="${k}" ${a.engine===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="provider">Fournisseur</label><select id="provider" name="provider"><option value="openai" ${a.provider==='openai'?'selected':''}>OpenAI</option><option value="codex" ${a.provider==='codex'?'selected':''}>ChatGPT · accès Codex personnel</option><option value="compatible" ${a.provider==='compatible'?'selected':''}>API compatible / local</option><option value="ollama" ${a.provider==='ollama'?'selected':''}>Ollama · modèle local</option></select></div>${textField('model','Identifiant du modèle',a.model,'text',true)}<datalist id="brain-models"></datalist>${button('Charger les modèles de mon compte','brain-models',null,'secondary small')}${textField('max_steps','Nombre maximal d’étapes',a.max_steps,'number',true)}</div><p class="hint">Appel direct utilise le fournisseur et le modèle choisis ici. Avec Dust, publiez la révision dans le workspace : le modèle est géré par l’agent Dust. Avec Pipelex, publiez la méthode : son modèle est déclaré dans la méthode. La connexion OAuth MCP de votre compte autorise des outils dans le chat ; elle ne configure pas ces moteurs API.</p></section><section class="card editor-section"><h3>03 · Harnais</h3>${textArea('skill','Skill · méthode de travail',a.skill,5)}${textArea('context','Contexte métier',a.context,3)}${textArea('memory','Mémoire validée par l’équipe',a.memory,3)}<p class="hint">La mémoire est éditée ici. Les résultats des exécutions ne la modifient pas automatiquement.</p></section><section class="card editor-section"><h3>04 · Boîte à outils</h3>${[['theses.read','Lire les notices autorisées'],['library.search','Rechercher dans la bibliothèque publiée'],['jinko.read','Consulter mon projet Jinkō via le SDK']].map(([k,n])=>`<label class="check"><input type="checkbox" name="tools" value="${k}" ${a.tools.includes(k)?'checked':''}>${n}</label>`).join('')}<div class="divider"></div><label>Connecteurs MCP accordés</label>${connectors.map(c=>`<label class="check"><input type="checkbox" name="connector_ids" value="${c.id}" ${a.connector_ids.includes(c.id)?'checked':''}>${esc(c.name)} · ${c.enabled?'activé':'désactivé'}</label>`).join('')||'<p class="tiny muted">Ajoutez un connecteur dans Connexions pour l’accorder à cet agent.</p>'}<p class="hint">Ces connecteurs concernent le moteur direct. Les outils OAuth Dust et Pipelex se règlent séparément dans Connexions et sont utilisés par le coordinateur après votre autorisation ; les écritures demandent une validation.</p></section><section class="card editor-section"><h3>05 · Méthode Pipelex</h3>${textField('method_ref','Référence de la méthode publiée',a.method_ref)}${textField('method_version','Version de méthode',a.method_version)}<p class="hint">Exportez le .mthds, publiez-le dans votre compte Pipelex puis renseignez sa référence. Le modèle est déclaré dans la méthode.</p></section></form>${a.id?`<section class="card editor-section"><h3>Contrôle & déploiement</h3>${d.live_control.length?`<ul class="tiny muted">${d.live_control.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:badge('Prérequis configurés — appel réel à vérifier','dark')}<div class="actions" style="margin-top:16px">${button('Exporter .mthds','export-agent',null,'secondary small',`data-id="${a.id}" data-target="pipelex"`)}${button('Exporter Dust','export-agent',null,'secondary small',`data-id="${a.id}" data-target="dust"`)}${button('Publier dans Dust','publish-dust','arrow','small',`data-id="${a.id}"`)}</div><details><summary>Harnais assemblé · dernière révision enregistrée</summary><pre>${esc(d.assembled)}</pre></details><details><summary>Historique · ${d.revisions.length} révision(s)</summary>${d.revisions.slice().reverse().map(r=>`<details><summary>v${r.revision} · ${fmt(r.saved_at)}</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`).join('')}</details></section>`:''}`;}
async function newAgent(){modal('Créer un agent',`<div class="eyebrow">Création guidée</div><h2>Quelle mission lui confier ?</h2><p class="muted">Un rôle prépare le contrat d’entrée/sortie. Vous personnaliserez ensuite le cerveau et chaque pièce du harnais.</p><div class="grid equal">${Object.entries(roleNames).map(([k,n])=>`<button class="card" style="text-align:left;cursor:pointer" data-action="forge-role" data-role="${k}"><span class="agent-icon">${icon('spark')}</span><h3 style="margin:16px 0 0">${n}</h3></button>`).join('')}</div>`,'','medium');}
async function forge(role){const base=S.data.agents.find(a=>a.role===role);await openAgent(base.id,true);S.editAgent.name=roleNames[role]+' personnalisé';$('#name').value=S.editAgent.name;}
async function testAgent(id){const a=S.data.agents.find(x=>x.id===id);modal('Tester · '+a.name,`<form id="agent-test-form" data-id="${id}" data-role="${a.role}"><p class="muted">Le test utilise la révision enregistrée, le mode ${S.mode==='demo'?'simulation':'réel'} et les données autorisées.</p>${a.role!=='rapprochement'?`<div class="field"><label for="test-thesis">Thèse</label><select name="thesis_id" id="test-thesis">${S.data.theses.map(t=>`<option value="${t.id}" ${t.id==='2014DIJOS078'?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div>`:''}${textArea('test-problem','Besoin / contexte du test',S.problem||SAMPLE,3)}<button class="btn" type="submit">${icon('spark')}Lancer le test</button></form><div id="modal-job"></div>`,'','medium');}
async function showRun(id){const r=await api('/runs/'+id);modal('Exécution · '+r.label,`<div class="pills">${badge(statusNames[r.status],r.status==='failed'?'red':'dark')}${badge(r.mode==='demo'?'Simulation':'Traitement','gray')}</div>${r.error?errorBox(r.error):''}<div class="timeline">${r.trace.map(t=>`<div class="event"><span class="event-dot"></span><div><p>${esc(t.message)}</p><small>${fmt(t.at)}</small></div></div>`).join('')}</div>${r.result?.content?renderReport(r.result):r.result?`<pre>${esc(JSON.stringify(r.result,null,2))}</pre>`:''}${r.agent_snapshot?`<details><summary>Harnais utilisé · snapshot</summary><pre>${esc(JSON.stringify(r.agent_snapshot,null,2))}</pre></details>`:''}`);}
async function connectorForm(id){if(!S.connections)S.connections=await api('/connections');const c=S.connections.connectors.find(x=>x.id===id)||{id:'',name:'',url:'',allowed_tools:[],secret_env:'',enabled:false};S.editConnector=c;modal(c.id?'Configurer le connecteur':'Ajouter un connecteur MCP',`<form id="connector-form">${textField('connector-name','Nom',c.name,'text',true)}${textField('connector-url','URL Streamable HTTP du serveur MCP',c.url,'url',true)}${textField('secret_env','Nom de la variable d’environnement contenant le jeton',c.secret_env)}${textArea('allowed_tools','Outils autorisés · un nom par ligne',c.allowed_tools.join('\n'),4)}<label class="check"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}>Activer ce connecteur</label><div class="notice info">Le test découvre les noms des outils. Accordez ensuite uniquement ceux qui seront utiles au harnais. Le serveur doit prendre en charge MCP Streamable HTTP ; l’authentification automatique OAuth n’est pas implémentée ici.</div><button class="btn" type="submit">Enregistrer</button></form>`,'','medium');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(await workspaceClick(a,b))return;
 if(a==='close')return closeModal();
 if(a==='nav')return await changeView(b.dataset.view);
 if(a==='refresh'){await refresh();return shell();}
 if(a==='thesis')return await openThesis(b.dataset.id,b.dataset.tab||'lecture');
 if(a==='detail-tab'){S.tab=b.dataset.tab;return renderThesis();}
 if(a==='sample'){S.problem=SAMPLE;$('#problem').value=SAMPLE;return;}
 if(a==='sample-inc'){S.problem=SAMPLE;$('#inc-problem').value=SAMPLE;return;}
 if(a==='sample-search'){S.problem=SAMPLE;return await changeView('library');}
 if(a==='clear-search'){S.search=null;return renderView();}
 if(a==='visibility'){await api('/theses/'+b.dataset.id+'/visibility',{method:'PATCH',body:JSON.stringify({visible:b.dataset.visible==='true'})});await refresh();S.detail=await api('/theses/'+b.dataset.id);renderThesis();return toast('Visibilité mise à jour.');}
 if(a==='correct'){const t=S.detail.thesis;return modal('Corriger le résumé',`<form id="correction-form">${textArea('summary','Votre résumé corrigé',t.correction||currentReport('lecteur')?.content.summary||t.abstract,10)}<p class="hint">Le résumé source et l’analyse de l’agent seront conservés.</p><button class="btn" type="submit">Enregistrer la correction</button></form>`,'','medium');}
 if(a==='generate'){b.disabled=true;await generate(b.dataset.role);b.disabled=false;return;}
 if(a==='export-report')return await download('/reports/'+b.dataset.id+'/export','passage-dossier.md');
 if(a==='export-lab')return await download('/laboratory/export','passage-indicateurs.csv');
 if(a==='import')return modal('Importer depuis theses.fr',`<form id="import-form"><p class="muted">La recherche récupère les notices puis filtre leur laboratoire partenaire. Les corrections et publications existantes sont conservées.</p>${textField('query','Requête',S.data.settings.lab_short+' '+S.data.settings.city,'text',true)}${textField('lab_filter','Nom du laboratoire partenaire','Réactivité et Chimie des Solides','text',true)}${textField('limit','Nombre maximal de résultats',100,'number',true)}<button class="btn" type="submit">${icon('download')}Lancer l’import réel</button></form>`,'','medium');
 if(a==='batch'){const j=await post('/read-batch',{mode:S.mode});watch(j,()=>shell());return;}
 if(a==='edit-lab')return modal('Configurer le laboratoire',`<form id="lab-form">${textField('lab_name','Nom du laboratoire',S.data.settings.lab_name,'text',true)}${textField('lab_short','Sigle',S.data.settings.lab_short,'text',true)}${textField('city','Ville',S.data.settings.city,'text',true)}<button class="btn" type="submit">Enregistrer</button></form>`,'','medium');
 if(a==='new-programme')return modal('Nouveau programme R&D',`<form id="programme-form">${textField('name','Nom du programme','','text',true)}${textArea('description','Besoin et contraintes','',5)}<button class="btn" type="submit">Créer le programme local</button></form>`,'','medium');
 if(a==='programme-search'){S.problem=S.data.programmes.find(p=>p.id===b.dataset.id).description;S.search=null;return await changeView('library');}
 if(a==='decide'){b.disabled=true;await post('/proposals/'+b.dataset.id+'/decision',{decision:b.dataset.decision});await refresh();shell();return toast(b.dataset.decision==='accepted'?'Proposition acceptée. La note est déposée.':'Proposition refusée. Aucune note déposée.');}
 if(a==='show-note'){const p=S.data.proposals.find(x=>x.id===b.dataset.id);return modal('Note au programme',`<h2>${esc(p.programme_name)}</h2><pre>${esc(p.note)}</pre>`);}
 if(a==='sync-oscar'){const j=await post('/programmes/sync');if(j.id)watch(j,()=>shell());else toast('Programmes locaux à jour.');return;}
 if(a==='new-agent')return await newAgent();
 if(a==='forge-role')return await forge(b.dataset.role);
 if(a==='edit-agent')return await openAgent(b.dataset.id);
 if(a==='duplicate-agent')return await openAgent(b.dataset.id,true);
 if(a==='test-agent')return await testAgent(b.dataset.id);
 if(a==='run-detail')return await showRun(b.dataset.id);
 if(a==='export-agent')return await download('/agents/'+b.dataset.id+'/export/'+b.dataset.target,'passage-agent.'+(b.dataset.target==='pipelex'?'mthds':'json'));
 if(a==='publish-dust'){const j=await post('/agents/'+b.dataset.id+'/publish-dust');watch(j,()=>openAgent(b.dataset.id));return;}
 if(a==='local-models'){const result=await api('/local-models');return modal('Modèles Ollama disponibles',result.models.map(m=>`<div class="list-line"><strong>${esc(m.name)}</strong><span class="muted tiny">${(m.size/1e9).toFixed(1)} Go</span></div>`).join('')||empty('Aucun modèle installé.'),'','medium');}
 if(a==='new-connector')return await connectorForm('');
 if(a==='edit-connector')return await connectorForm(b.dataset.id);
 if(a==='test-connector'){const j=await post('/connectors/'+b.dataset.id+'/test');watch(j,()=>showRun(j.id));return;}
 }catch(err){b.disabled=false;toast(err.message,true);if($('#modal-error'))$('#modal-error').innerHTML=errorBox(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const data=new FormData(f);const submit=f.querySelector('[type=submit]')||document.querySelector(`[form="${f.id}"]`);if(submit)submit.disabled=true;try{
 if(await workspaceSubmit(f,data))return;
 if(f.id==='filter-form'){S.filter=data.get('query');S.status=data.get('status');renderView();}
 if(f.id==='search-form'){S.problem=data.get('problem');localStorage.setItem('passage-problem',S.problem);const j=await post('/runs',{role:'rapprochement',problem:S.problem,mode:S.mode});watch(j,result=>{S.search=result;shell();});}
 if(f.id==='incorporation-form'){S.problem=data.get('problem');await generate('incorporation');}
 if(f.id==='followup-form'){const r=currentReport('incorporation');S.problem=r.problem;await generate('incorporation',data.get('question'));}
 if(f.id==='correction-form'){await api('/theses/'+S.detail.thesis.id+'/correction',{method:'PATCH',body:JSON.stringify({summary:data.get('summary')})});S.detail=await api('/theses/'+S.detail.thesis.id);renderThesis();toast('Correction conservée.');}
 if(f.id==='import-form'){const j=await post('/import',{query:data.get('query'),lab_filter:data.get('lab_filter'),limit:Number(data.get('limit'))});closeModal();watch(j,()=>shell());}
 if(f.id==='lab-form'){await api('/laboratory',{method:'PATCH',body:JSON.stringify(Object.fromEntries(data))});closeModal();await refresh();shell();}
 if(f.id==='programme-form'){await post('/programmes',Object.fromEntries(data));closeModal();await refresh();shell();}
 if(f.id==='proposal-form'){const r=currentReport('incorporation');await post('/proposals',{thesis_id:S.detail.thesis.id,programme_id:data.get('programme'),report_id:r.id});closeModal();await changeView('programmes');toast('Proposition créée. Le chef de programme peut décider.');}
 if(f.id==='agent-form'){const body=Object.fromEntries(data);body.active=data.has('active');body.max_steps=Number(data.get('max_steps'));body.tools=data.getAll('tools');body.work_specialties=data.getAll('work_specialties');body.connector_ids=data.getAll('connector_ids');const a=await api('/agents'+(S.editAgent.id?'/'+S.editAgent.id:''),{method:S.editAgent.id?'PUT':'POST',body:JSON.stringify(body)});await refresh();shell();await openAgent(a.id);toast('Harnais enregistré · révision '+a.revision);}
 if(f.id==='agent-test-form'){const j=await post('/runs',{role:f.dataset.role,agent_id:f.dataset.id,thesis_id:data.get('thesis_id')||null,problem:data.get('test-problem'),mode:S.mode});watch(j,()=>showRun(j.id));}
 if(f.id==='connections-form'){const body=Object.fromEntries([...data].filter(([k,v])=>!k.endsWith('KEY')&&k!=='OSCAR_TOKEN'||v.trim()));body.persist_settings=data.has('persist_settings');await post('/connections/settings',body);await refresh();await loadConnections();toast(body.persist_settings?'Paramètres conservés sur cette installation.':'Paramètres appliqués à cette session.');}
 if(f.id==='connector-form'){const body={name:data.get('connector-name'),url:data.get('connector-url'),secret_env:data.get('secret_env'),allowed_tools:data.get('allowed_tools').split('\n').map(x=>x.trim()).filter(Boolean),enabled:data.has('enabled')};await api('/connectors'+(S.editConnector.id?'/'+S.editConnector.id:''),{method:S.editConnector.id?'PUT':'POST',body:JSON.stringify(body)});closeModal();await loadConnections();toast('Connecteur enregistré.');}
 }catch(err){toast(err.message,true);if($('#modal-error'))$('#modal-error').innerHTML=errorBox(err.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.id==='role-select'){if(S.liveVoice)await stopLiveVoice();if(S.voiceConversation)await stopVoiceConversation();S.role=e.target.value;S.view={lab:'lab',company:'library',researcher:'researcher',admin:'agents'}[S.role];S.search=null;await refresh();shell();}});
document.addEventListener('keydown',e=>{const dialog=$('.dialog');if(!dialog)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
